"""Discount rates for VIP tiers and promotional coupons."""

from decimal import Decimal, ROUND_HALF_UP
from datetime import date

CENT = Decimal("0.01")
VIP_TIERS = {"VIP_SILVER": Decimal("0.05"), "VIP_GOLD": Decimal("0.12")}
MAX_STACKED_RATE = Decimal("0.30")

class ClarificationNeeded(Exception): ...
class CouponExpired(Exception): ...

def compute_discount_rate(
    coupon: dict | None, vip_tier: str | None, now_ts: int, subtotal: Decimal = Decimal("0")
) -> Decimal:
    """Return the order discount rate: the VIP tier rate plus the coupon rate, if any, capped at 30%."""
    if vip_tier is None:
        raise ClarificationNeeded("Which VIP tier: VIP_SILVER (5%) or VIP_GOLD (12%)?")

    rate = VIP_TIERS[vip_tier]

    if coupon is not None:
        coupon_expires_on = date.fromtimestamp(coupon["expires_at"])
        today = date.fromtimestamp(now_ts)
        if today > coupon_expires_on:
            raise CouponExpired(coupon["code"])
        rate += Decimal(str(coupon["rate"]))

    return min(rate, MAX_STACKED_RATE)

